def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.35))

    total_agents = 1 + len(alive_opponents)
    total_req = WATER_REQ + sum(opp_requirements)
    scarcity_ratio = float(supply) / float(total_req) if total_req > 0 else 1.0
    per_agent_supply = float(supply) / float(total_agents)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1
    very_tight = scarcity_ratio < 0.34 or per_agent_supply < 4.2
    tight = scarcity_ratio < 0.42 or per_agent_supply < 5.2
    comfortable_supply = scarcity_ratio > 0.52 and per_agent_supply > 6.0

    if urgent:
        target = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif very_tight:
        target = max(DAILY_SALARY * 0.82, avg_prev + 2.0, highest_prev * 0.92)
    elif tight:
        if highest_prev >= DAILY_SALARY * 0.9:
            target = DAILY_SALARY * 0.52 if hp > 5 and no_water_days == 0 else DAILY_SALARY * 0.88
        else:
            target = max(DAILY_SALARY * 0.58, avg_prev * 0.72 + 4.0)
    elif comfortable_supply:
        target = DAILY_SALARY * 0.22 if hp > 5 and no_water_days == 0 else DAILY_SALARY * 0.4
    else:
        if pressured:
            target = max(DAILY_SALARY * 0.62, avg_prev * 0.62 + 3.0)
        else:
            target = DAILY_SALARY * 0.34

    rich_threshold = DAILY_SALARY * 10
    if budget < DAILY_SALARY * 2:
        target *= 0.9
    elif budget > rich_threshold and pressured:
        target *= 1.08

    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.98)
    elif hp >= 8 and no_water_days == 0 and comfortable_supply:
        target = min(target, DAILY_SALARY * 0.28)

    target = max(0.0, min(float(budget), float(target)))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
        if prev.get('hp_after') is not None:
            prev_hp_after.append(float(prev['hp_after']))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # If others were very aggressive yesterday, we must raise to keep up.
    aggressive_threshold = DAILY_SALARY * 0.85  # 76.5

    # Base target: aim to beat the highest recent bid with a small premium,
    # but cap to avoid overspending.
    # Since supply is limited (15-25), winning likely requires paying near competitors.
    if highest_prev_bid >= aggressive_threshold:
        if hp > 3:
            target = max(highest_prev_bid + 5.0, DAILY_SALARY * 0.35)
        else:
            target = max(highest_prev_bid + 10.0, DAILY_SALARY * 0.9)
    else:
        # If nobody was that aggressive, bid moderately above a typical level.
        target = max(DAILY_SALARY * 0.55, highest_prev_bid + 2.0)

    # React to my own risk.
    # If my no_water_days is high, I should secure water more aggressively.
    if no_water_days >= 2:
        target *= 1.15
    if hp <= 2:
        target *= 1.25

    # Convert target to a feasible bid given budget.
    # Keep a hard cap relative to daily salary to avoid running out.
    hard_cap = DAILY_SALARY * 1.2
    bid = float(min(budget, hard_cap, target))

    # Ensure non-negative and at least a minimal bid.
    if bid < 1.0:
        bid = float(min(budget, 1.0))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.7)

    avg_prev = sum(yesterday_bids) / len(yesterday_bids)
    max_prev = max(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5.0)

    if supply < (WATER_REQ * (len(alive_opponents) + 1)):
        return min(my_status['budget'], max_prev * 1.05)

    return min(my_status['budget'], max(DAILY_SALARY * 0.6, avg_prev * 0.9))
